INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'One Piece', 'Le avventure di Monkey D. Luffy e della sua ciurma alla ricerca del tesoro leggendario per diventare il Re dei Pirati.', '/images/manga/one_piece.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Berserk', 'La storia oscura e violenta di Guts, il Guerriero Nero, nel suo viaggio di vendetta contro la Mano di Dio.', '/images/manga/berserk.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Fullmetal Alchemist', 'I fratelli Elric cercano la Pietra Filosofale per ripristinare i loro corpi dopo un esperimento alchemico fallito.', '/images/manga/fma.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Monster', 'Il brillante neurochirurgo Kenzo Tenma insegue un suo ex paziente, rivelatosi un pericoloso e geniale serial killer.', '/images/manga/monster.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Vagabond', 'Una rilettura romanzata della vita di Miyamoto Musashi, il più grande spadaccino della storia giapponese.', '/images/manga/vagabond.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Hunter x Hunter', 'Gon Freecss intraprende l''esame per diventare un Hunter e ritrovare suo padre scomparso da tempo.', '/images/manga/hxh.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Death Note', 'Uno studente brillante trova un quaderno soprannaturale in grado di uccidere chiunque vi abbia il nome scritto sopra.', '/images/manga/death_note.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Dragon Ball', 'Le iconiche avventure di Son Goku, dalle arti marziali alla difesa dell''universo contro minacce intergalattiche.', '/images/manga/dragon_ball.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Naruto', 'Un giovane ninja reietto cerca costantemente approvazione e sogna di diventare l''Hokage del suo villaggio.', '/images/manga/naruto.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'JoJo''s Bizarre Adventure', 'Le bizzarre avventure generazionali della famiglia Joestar, in lotta contro vampiri, utilizzatori di stand e forze oscure.', '/images/manga/jojo.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'L''attacco dei Giganti', 'L''umanità vive rintanata all''interno di enormi mura per proteggersi dai Titani, gigantesche creature antropofaghe.', '/images/manga/aot.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Vinland Saga', 'Il giovane vichingo Thorfinn viaggia insieme all''assassino di suo padre in cerca di vendetta e del leggendario regno di Vinland.', '/images/manga/vinland_saga.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Slam Dunk', 'Hanamichi Sakuragi, un teppista liceale, si unisce alla squadra di basket per fare colpo su una ragazza, scoprendo una vera passione.', '/images/manga/slam_dunk.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Akira', 'In una neo-Tokyo post-apocalittica, un gruppo di motociclisti si scontra con poteri psichici governativi segreti.', '/images/manga/akira.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Neon Genesis Evangelion', 'Adolescenti pilotano giganteschi mecha biomeccanici per difendere la Terra da creature misteriose chiamate Angeli.', '/images/manga/evangelion.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Demon Slayer', 'Tanjiro Kamado diventa un cacciatore di demoni per vendicare la sua famiglia e curare la sorella trasformata in demone.', '/images/manga/demon_slayer.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Jujutsu Kaisen', 'Uno studente del liceo ingoia un talismano maledetto e si unisce a un''organizzazione segreta di stregoni per combattere le maledizioni.', '/images/manga/jujutsu_kaisen.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Chainsaw Man', 'Un giovane in miseria si fonde con il suo cane-motosega demoniaco ed entra a far parte dei cacciatori di diavoli della pubblica sicurezza.', '/images/manga/chainsaw_man.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'Bleach', 'Ichigo Kurosaki ottiene i poteri di un Dio della Morte e deve proteggere gli umani dagli spiriti maligni chiamati Hollow.', '/images/manga/bleach.jpg');
INSERT INTO manga (id, nome, descrizione, path_immagine) VALUES (nextval('manga_seq'), 'My Hero Academia', 'In un mondo in cui quasi tutti hanno dei superpoteri, un ragazzo nato senza abilità sogna di diventare l''eroe numero uno.', '/images/manga/mha.jpg');